/* Shorter case-study drills (6–20 marks). One ILAC answer each, marked against the scheme. */
(function (LL) {
  'use strict';
  function drill(o) { o.kind = o.kind || 'drill'; o.mins = o.mins || Math.round(o.marks * 1.2 + 3); LL.addCase(o); }
  function one(ask, marks, name, ch, points, model, tricks) {
    return [{ label: '', marks: marks, ask: ask, issues: [{ name: name, ch: ch, points: points }], model: model, tricks: tricks || [] }];
  }

  drill({ id: 'kfm', title: 'James and KFM Property Agency', src: 'Practice paper, sample case study 1', chs: [10], marks: 15, parties: ['James', 'KFM'],
    facts: 'James hired KFM Property Agency ("the Agency") to sell four of his industrial units for an agreed commission of 2%. It was also agreed that James would pay for KFM\'s expenses incurred for this purpose.\n\nThe Agency sold the units and earned the agreed commission from James. However, the Agency had enjoyed a discount when it incurred advertising, marketing and printing expenses for James in relation to the sale. Although the discount was a custom of the trade, the practice was not known to James. (The paper calls the principal "Jacob" once.)',
    parts: one('Discuss the legal position of the Agency and James. (15 marks)', 15, 'Secret profit by an honest agent', 10, [
      { t: 'KFM is James\'s agent and a fiduciary: duties of good faith, disclosure, no conflict, no secret profit.', m: 3, k: ['fiduciar', 'secret profit|disclos'] },
      { t: 'Charging full price while paying a discounted price is a secret profit; a trade custom unknown to the principal is no defence (Hippisley v Knee Bros).', m: 4, k: ['hippisley|knee', 'custom'] },
      { t: 'Disclosure and consent would have cured it; on the facts James was never told.', m: 2, k: ['consent|disclos'] },
      { t: 'Remedy: KFM must account for / repay the discounts; reimbursement only for expenses actually incurred.', m: 3, k: ['account|repay|reimburs'] },
      { t: 'Commission: an honest agent keeps the earned commission (Hippisley); forfeiture is for dishonest agents (Andrews v Ramsay); CEA Code reflects the same principles.', m: 3, k: ['commission', 'andrews|honest'] }
    ], '**Issue.** (1) Did KFM breach a fiduciary duty by keeping the trade discounts? (2) What may James recover or withhold?\n\n**Law.** An agent owes fiduciary duties of good faith, disclosure and loyalty, must not make a secret profit and must account for it (**Hippisley v Knee Brothers**). A custom of the trade does not excuse the agent where the principal did not know of it (**Hippisley**). A disclosed profit with the principal\'s consent is allowed. A dishonest agent may also forfeit commission (**Andrews v Ramsay**). A CEA-regulated agent must also meet the Code of Ethics.\n\n**Application.** KFM charged James for third-party services at full price while paying a discounted price, keeping a secret profit from its position. KFM acted honestly in following industry practice, but honesty is no defence to the strict rule, and a custom James did not know of and did not agree to cannot override the duty of disclosure. Had KFM disclosed and James consented, there would be no breach. Remedies: James may require KFM to account for the discounts; KFM can claim reimbursement only for the expenses it actually incurred. KFM likely keeps its 2% commission, earned on completed sales by an honest agent (Hippisley), although James may argue disloyalty justifies forfeiture (Andrews v Ramsay) [check].\n\n**Conclusion.** KFM breached its fiduciary duty and must account to James for the discounts. It will probably keep its commission because it acted honestly.') });

  drill({ id: 'printwell', title: 'Printwell and Costco', src: 'Practice paper, sample case study 2', chs: [4], marks: 15, parties: ['Printwell', 'Costco'],
    facts: 'Printwell Pte Ltd operated a four-storey printing factory on industrial land ("the Factory"). Costco Enterprises owned the adjoining land and shared a common boundary with Printwell.\n\nIn 2024 Costco began excavation and piling works to construct a basement car park on its land. The works involved cutting close to the common boundary. As advised by Costco\'s engineers, its contractor installed sheet piles as support. However, Costco did not implement a continuous monitoring regime over the works. Within weeks, cracks appeared on the access roads and pavements on Costco\'s land. There was also damage to the Factory due to soil settlement, and the Factory was forced to suspend operations.\n\n(The paper writes "Cosco", "Costco" and "Basco" for the same neighbour.)',
    parts: one('Discuss Printwell\'s and Costco\'s legal positions. (15 marks)', 15, 'Right of support and negligence', 4, [
      { t: 'Natural right of support from adjoining land; the neighbour must secure alternative support before removing soil.', m: 3, k: ['natural right|right of support', 'alternative support|support'] },
      { t: 'English line: buildings need an easement of support (Dalton v Angus); Singapore: Xpress Print v Monocrafts extends the duty to buildings.', m: 4, k: ['xpress print|monocrafts', 'dalton|building'] },
      { t: 'Engineers\' advice does not displace Costco\'s own duty; Costco may seek contribution from its engineers or contractor.', m: 2, k: ['engineer|contractor|contribution'] },
      { t: 'Negligence: foreseeable damage; no continuous monitoring despite early warning cracks; consequential loss of profit recoverable as it follows physical damage.', m: 4, k: ['negligen', 'monitor', 'loss of profit|consequential|suspen'] },
      { t: 'Costco\'s replies (building weight, engineers\' advice, mitigation) and Printwell\'s injunction to halt works until support is secured; conclusions for both.', m: 2, k: ['injunction|mitigat'] }
    ], '**Issue.** (1) Is Costco liable to Printwell for the damage to its land and factory? (2) What can Printwell recover, and what can Costco say in reply?\n\n**Law.** A landowner has a natural right of support from adjoining soil; the neighbour must secure alternative support before removing soil. In **Xpress Print v Monocrafts** the Court of Appeal held the duty extends to the claimant\'s property, including buildings, and was breached where soil was removed without sufficient alternative support. Under English authority the natural right protects land only, and a building needs an easement of support (**Dalton v Angus**), so state both. A claim also lies in negligence; consequential loss that follows physical damage is recoverable. The cause of action arises when the damage happens (**Backhouse v Bonomi**).\n\n**Application.** Costco excavated next to the boundary and settlement followed within weeks: it removed support without sufficient alternative support. Xpress Print extends the duty to the factory, so Printwell needs no easement. Following engineers\' advice does not displace Costco\'s duty as the landowner doing the works; Costco can seek contribution from its engineers or contractor. In negligence, damage to a four-storey factory beside a basement dig was foreseeable; Costco set up no continuous monitoring, and cracks on its own roads gave early warning. Heads of loss: repair costs and loss of profit during the suspension. Costco\'s answers: the building\'s weight contributed; the works followed engineers\' advice; Printwell must mitigate. Printwell can seek an injunction to stop further works until support is secured.\n\n**Conclusion.** Printwell has strong claims under Xpress Print and in negligence, including loss of profit. Costco should secure the site, notify Printwell and seek contribution from its engineers and contractor.') });

  drill({ id: 'ong', title: 'Mr Ong, Seng, Bobby and Harbour Bank', src: 'Q&A Bank, Question A', chs: [9], marks: 20, parties: ['Mr Ong', 'Bobby', 'Harbour Bank'],
    facts: 'Mr Ong is the registered proprietor of a terrace house at Lorong Ah Soo worth about $2.4m. While he worked in Shanghai, his nephew Seng forged his signature on a transfer of the house to Seng\'s friend Bobby for $900,000. Bobby\'s lawyer warned him that the "Mr Ong" signature looked nothing like the specimen on file and that the price was far below market. Bobby replied: "Don\'t ask so many questions, just register it." Bobby paid Seng in cash. The transfer was registered in Bobby\'s name.\n\nA month later Bobby mortgaged the house to Harbour Bank for $1.5m. Harbour Bank carried out its usual checks, dealt only with Bobby as registered proprietor, had no reason to suspect anything and registered its mortgage. Bobby has stopped paying. Mr Ong has just returned.',
    parts: one('Advise Mr Ong. (20 marks)', 20, 'Torrens: forgery and indefeasibility', 9, [
      { t: 'Registration is the root of title; s 46(1) immediate indefeasibility (Frazer v Walker); only purchasers in good faith for value benefit (s 4; s 46(3)).', m: 4, k: ['§46|indefeasib', 'frazer'] },
      { t: 's 46(2)(a): fraud or forgery by the proprietor or his agent; fraud = actual dishonesty (Assets Co; UOB v Bebe); wilful blindness counts (Waimiha).', m: 4, k: ['§46|fraud', 'bebe|assets co|mere roihi', 'wilful|waimiha'] },
      { t: 'Bobby: warned about signature and price, refused inquiry: wilful blindness; also not a purchaser in good faith; title defeasible.', m: 4, k: ['bobby', 'warn|suspic|blind'] },
      { t: 'Harbour Bank: innocent purchaser for value; Bobby\'s fraud is not the bank\'s (not its agent); s 47(1); charge indefeasible (as in Bebe).', m: 4, k: ['harbour|bank', 'innocent|good faith|§47'] },
      { t: 'Remedies: rectification s 160 (house returns subject to the charge); caveat s 115; sue Seng and Bobby; Assurance Fund (ss 151, 155) unlikely without Registry error.', m: 4, k: ['§160|rectif', 'assurance fund|§155|§151', 'caveat|§115'] }
    ], '**Issue.** (1) Is Bobby\'s registered title indefeasible? (2) Does Harbour Bank\'s mortgage bind Mr Ong? (3) What remedies does Mr Ong have?\n\n**Law.** Registration is the root of title (**s 45 LTA**; **Breskvar v Wall**). Under **s 46(1)** a registered proprietor holds free of encumbrances; Singapore follows immediate indefeasibility (**Frazer v Walker**). Only a purchaser in good faith for value benefits (**s 4**; **s 46(3)**). **s 46(2)(a)** removes protection where the proprietor or his agent was party to fraud or forgery. Fraud means actual dishonesty (**Assets Co v Mere Roihi**; **UOB v Bebe**; s 47(2)); deliberately shutting one\'s eyes after suspicion is aroused is akin to fraud (**Waimiha Sawmilling**). The court may rectify (**s 160**); the Assurance Fund compensates Registry error (**ss 151, 155**).\n\n**Application.** Bobby: his lawyer warned him that the signature did not match and that $900,000 was far below the $2.4m value; suspicion was aroused, and "Don\'t ask so many questions, just register it" is a decision to avoid the truth: wilful blindness. Paying cash and pressing for registration support dishonesty. s 46(2)(a) applies and he is not a purchaser in good faith. Harbour Bank dealt with the registered proprietor, made its usual checks and had no reason to suspect; Bobby\'s fraud is not the bank\'s (he is not its agent), and s 47(1) means it need not look behind the register. As in Bebe, the innocent mortgage is indefeasible even though Bobby\'s title is not. Remedies: Mr Ong applies under s 160 to cancel Bobby\'s registration; the house returns to him subject to the charge. He should caveat at once (s 115) and sue Seng and Bobby. The Assurance Fund will not respond to Seng\'s forgery alone; there is no sign of Registry error.\n\n**Conclusion.** Bobby\'s title is defeasible and Mr Ong can recover the house, but subject to Harbour Bank\'s indefeasible $1.5m mortgage. He should recover his loss from Seng and Bobby.', ['Take each registered person in turn: purchaser? fraud by that person? overriding interest?', 'Name the safety nets: rectification, caveat, claim against the wrongdoer, and the Assurance Fund (and why it probably fails).']) });

  drill({ id: 'lee', title: 'The Lees, Kelvin, Star Realty and Orchid Holdings', src: 'Q&A Bank, Question B', chs: [10], marks: 20, parties: ['the Lees', 'Kelvin', 'Star Realty', 'Orchid'],
    facts: 'Mr and Mrs Lee appointed Uncle Kelvin, a CEA-registered salesperson with Star Realty, to sell their Toa Payoh condominium unit at 1% commission payable on completion. Kelvin told them the market was "very quiet" and that only Orchid Holdings Pte Ltd had offered, at $1.18m. Two independent valuations put the unit at about $1.25m. In fact two other buyers had offered $1.32m, and Kelvin never passed those offers on. Orchid Holdings is owned by Kelvin\'s cousin. Kelvin also received a $4,000 "appreciation fee" from Orchid. The Lees granted Orchid an OTP, which has been exercised. Completion is next month. The Lees have just discovered the truth.',
    parts: one('Advise the Lees of their rights against Kelvin, Star Realty and Orchid Holdings. (20 marks)', 20, 'Fiduciary breach and bribery', 10, [
      { t: 'Kelvin is a fiduciary: undisclosed conflict in steering the sale to his cousin\'s company (McPherson v Watt).', m: 4, k: ['fiduciar', 'mcpherson|conflict|cousin'] },
      { t: 'Withholding the $1.32m offers breaches the duties to disclose, follow instructions and use care; loss about $140,000.', m: 4, k: ['offer|disclos', '140|1\\.32'] },
      { t: 'The $4,000 is a bribe: account; constructive trust (FHR v Cedar); dishonest agent forfeits commission (Andrews v Ramsay; contrast Hippisley).', m: 5, k: ['bribe|secret commission', 'fhr|cedar|constructive trust', 'andrews|forfeit'] },
      { t: 'Against Orchid: rescind the exercised OTP before completion (act promptly, restore position, avoid affirming) or affirm and claim damages.', m: 4, k: ['rescind|rescission', 'orchid'] },
      { t: 'Star Realty may be liable for its salesperson [check basis]; CEA complaint; Prevention of Corruption Act in one line.', m: 3, k: ['star realty', 'cea|code of ethics|corruption'] }
    ], '**Issue.** (1) Did Kelvin breach his fiduciary duties by steering the sale to his cousin\'s company and withholding higher offers? (2) What follows from the $4,000 fee? (3) Can the Lees escape the contract with Orchid, and what can they claim from Orchid and Star Realty?\n\n**Law.** An estate agent is a fiduciary: good faith, no conflict, disclosure of material information, no secret profit. He may not sell to a connected party without full disclosure and consent (**McPherson v Watt**), and must pass on every offer. A payment from the other side without the principal\'s knowledge is a bribe: the agent must account, a dishonest agent forfeits commission (**Andrews v Ramsay**; contrast **Hippisley v Knee Bros**), and the bribe is held on constructive trust (**FHR v Cedar Capital**). A contract obtained by bribing the agent can be rescinded.\n\n**Application.** Orchid is owned by Kelvin\'s cousin, undisclosed: a conflict. He called the market "very quiet" and hid two $1.32m offers: breach of disclosure, instructions and care, causing a loss of about $140,000. The $4,000 came from the buyer, in secret, linked to a below-market sale: a bribe. Kelvin was dishonest, so Hippisley does not help; he forfeits his 1% and holds the $4,000 on constructive trust. Before completion the Lees can rescind the OTP, returning what they received, and must not affirm; or they can affirm and claim damages from Kelvin and Orchid. Star Realty may be liable for its salesperson [check basis], and the Lees can complain to the CEA.\n\n**Conclusion.** Kelvin is liable for about $140,000, must give up the $4,000 and forfeits commission. The Lees should rescind before completion (or affirm and sue), look to Star Realty, and report Kelvin to the CEA.', ['List the bribe remedies: account, constructive trust, rescission, forfeit commission.', 'Name the conflict (cousin) and the suppressed offers as two breaches.']) });

  drill({ id: 'punggol', title: 'Marcus, Mr Lee and the Punggol unit', src: 'Q&A Bank, Question C (10 marks, 15 minutes)', chs: [8, 9], marks: 10, mins: 15, parties: ['Marcus'],
    facts: 'Marcus found a three-bedroom unit in Punggol owned by Mr Lee. Over two weeks they negotiated on WhatsApp. Every message from Mr Lee ended with "subject to contract". They agreed on $1.18m, completion in 10 weeks, and that the curtains and aircon would be included. Marcus paid $1,000 by PayNow with the note "goodwill deposit". Mr Lee replied: "Ok received. Lawyer will send OTP Monday, subject to contract ya." On Sunday another buyer offered $1.25m. Mr Lee granted that buyer an OTP and messaged Marcus: "Sorry, deal off. Will refund." Marcus still wants the unit and is thinking of lodging a caveat.',
    parts: one('Advise Marcus on whether a binding contract was formed and what remedies are available. (10 marks)', 10, 'Subject to contract, writing and caveat', 8, [
      { t: 'Norwest (strong presumption of no contract) and OCBC v Wong Hua Choon (all the circumstances, objective intention); older strict view in Tai Tong.', m: 3, k: ['norwest', 'ocbc|wong hua choon'] },
      { t: 'Apply: label repeated even in the last message; OTP still to be sent; no signed document; the $1,000 is not an option fee: likely no contract.', m: 3, k: ['otp|option', 'goodwill|1,?000|option fee'] },
      { t: 'If a contract existed: s 6(d) writing (emails accepted; WhatsApp arguable) or part performance (small payment equivocal); specific performance.', m: 2, k: ['6a?\\s*\\(d\\)|writing|part performance'] },
      { t: 'No contract, no caveatable interest (s 115); a wrongful caveat risks s 128 compensation and s 127 removal; recover the $1,000.', m: 2, k: ['caveat', '§128|§127|recover|refund'] }
    ], '**Issue.** (1) Was a binding contract formed? (2) If so, is it enforceable and what remedies does Marcus have? (3) Can he caveat and recover the $1,000?\n\n**Law.** "Subject to contract" is not conclusive but creates a strong presumption of no contract until a formal contract is made (**Norwest v Newport Mining**); the court looks at all the circumstances and the objective evidence (**OCBC v Wong Hua Choon**; contrast the older **Tai Tong v Galstaun**). A land contract needs signed writing (**s 6(d) CLA**) or part performance. Only a person claiming an interest in land may caveat (**s 115 LTA**); a wrongful caveat risks compensation (**s 128**) and removal (**s 127**).\n\n**Application.** Every message from Mr Lee, including his reply to the payment, carried the label, and he said his lawyer would send the OTP on Monday: both expected a formal document first. Agreement on price and inclusions does not rebut the presumption; the $1,000 "goodwill deposit" is no option fee. This is unlike OCBC, where a common firm of solicitors and a settled deal supported a contract. If a contract did exist, the messages might satisfy s 6(d) [check WhatsApp], and specific performance would be a real prospect. With no contract, Marcus has no equitable interest and no caveatable interest; a caveat would expose him to s 128. The $1,000 was paid for an OTP that never came and is recoverable; Mr Lee has already promised a refund.\n\n**Conclusion.** Likely no binding contract. Marcus should not caveat; he should recover the $1,000, and next time insist on a signed OTP.', ['State both Norwest and OCBC, pick a side, give two facts.', 'A "no contract" answer still deals with the caveat and the money.']) });

  /* ---- Q&A Bank problem questions, Lots 1–6 ---- */
  drill({ id: 'q1', title: 'Ravi\'s fittings at the end of the lease', src: 'Q&A Bank, Q1', chs: [1], marks: 8, parties: ['Ravi', 'Mdm Sim'],
    facts: 'Ravi leased a shop from Mdm Sim for 5 years. He installed (a) glass display cabinets bolted to the floor, (b) a neon sign bolted to the shopfront, (c) a free-standing walk-in chiller resting on its own weight, and (d) a decorative chandelier hung from the ceiling. The lease ended on 30 June. Ravi was away until 10 July. On 11 July he came to remove the items. Mdm Sim says everything belongs to her.',
    parts: one('Advise Ravi and Mdm Sim. (8 marks)', 8, 'Fixtures and the tenant\'s window', 1, [
      { t: 'Two tests: degree and object of annexation (Holland v Hodgson); purpose weighs more (D\'Eyncourt).', m: 2, k: ['holland|hodgson|annexation', 'purpose|object'] },
      { t: 'Item by item: cabinets and sign are trade fixtures; chiller is a chattel; chandelier an ornamental fixture.', m: 3, k: ['trade fixture', 'chattel', 'ornamental|chandelier'] },
      { t: 'Timing: removal during the lease or a short time after, making good damage; items left after giving up possession pass to the landlord (BP Refinery [check]); Ravi likely loses the fixtures but keeps the chiller.', m: 3, k: ['make good|making good|short time|reasonable time', 'possession|landlord'] }
    ], '**Issue.** Which items are fixtures, and can Ravi still remove them?\n\n**Law.** Items attached to land are presumed fixtures; items resting on their own weight are presumed chattels; the tests are degree and object of annexation (**Holland v Hodgson**), and purpose now weighs more (**D\'Eyncourt v Gregory**). A tenant may remove trade, ornamental and domestic fixtures during the lease or a short time after, making good damage (**Fisher v Dixon**; **Spyers v Phillipson**). Items left after possession is given up belong to the landlord (**BP Refinery** [check]).\n\n**Application.** (a) Cabinets: bolted but for displaying his goods: trade fixtures. (b) Sign: fixed, advertising his business: a trade fixture, damage to be made good. (c) Chiller: rests on its weight and serves his trade: a chattel he may take at any time. (d) Chandelier: wired in to enhance the shop: an ornamental fixture. Timing: Ravi came 11 days after the end, after giving up possession, so Mdm Sim\'s position on the fixtures is strong, though Ravi may argue he was away for good reason and she suffered no loss [check what counts as a reasonable time].\n\n**Conclusion.** Ravi keeps the chiller. The three fixtures probably belong to Mdm Sim.') });

  drill({ id: 'q2', title: 'The crane, the drone and the anchors', src: 'Q&A Bank, Q2', chs: [1], marks: 8, parties: ['Mrs Tan'],
    facts: 'A developer\'s tower crane swings its jib 40 m above Mrs Tan\'s bungalow. A property blogger flies a drone at 25 m over her garden and posts the photographs. The developer\'s basement uses ground anchors that extend 12 m into the soil under her land.',
    parts: one('Advise Mrs Tan. (8 marks)', 8, 'Airspace and subsoil', 1, [
      { t: 'Airspace limited to what is reasonably necessary for ordinary use and enjoyment (s 2 LTA; Bernstein v Skyviews); low intrusions are trespass (Kelsen; Anchor Brewhouse).', m: 3, k: ['bernstein|skyviews|§2', 'kelsen|anchor brewhouse'] },
      { t: 'Crane at 40 m: arguable either way (Anchor Brewhouse v Bernstein); drone at 25 m: close enough for trespass to be arguable; privacy is separate.', m: 2, k: ['crane', 'drone'] },
      { t: 'Anchors at 12 m: within the 30 m default depth under s 3B State Lands Act, so trespass; injunction, removal or a price; contrast Bocardo (England).', m: 3, k: ['3b|state lands', '30 ?m|anchor'] }
    ], '**Issue.** Which of the three intrusions is trespass?\n\n**Law.** The owner holds the airspace reasonably necessary for ordinary use and enjoyment (**s 2 LTA**; **Bernstein v Skyviews**); intrusion within it is trespass (**Kelsen v Imperial Tobacco**; **Anchor Brewhouse**). Subsoil extends only to the depth reasonably necessary, or 30 m below the Singapore Height Datum if the title is silent (**s 3B State Lands Act**); England is wider (**Bocardo**).\n\n**Application.** Crane: Anchor Brewhouse treated a swinging jib as trespass; Bernstein limits Mrs Tan to the height a bungalow needs, which is far below 40 m. Present both and lean towards the developer on height, noting repeated swinging supports an injunction. Drone: 25 m over a garden is within the zone of ordinary use, unlike Bernstein\'s aircraft, so trespass is arguable. Anchors: 12 m is within 30 m, so trespass unless she agreed; she can seek an injunction, removal or a payment for the right.\n\n**Conclusion.** Good claim on the anchors, reasonable claim on the drone, arguable on the crane.') });

  drill({ id: 'q3', title: 'Hana\'s unregistered 9-year lease', src: 'Q&A Bank, Q3', chs: [2, 6, 9], marks: 8, parties: ['Hana', 'Dev'],
    facts: 'Hana signed an agreement with Ms Goh to lease Ms Goh\'s shop for 9 years. They signed a document headed "Tenancy Agreement" but made no deed and registered nothing. Hana took possession and paid rent. Ms Goh then sold the shop to Dev, who registered the transfer. Dev says Hana is a tenant at will and must leave.',
    parts: one('Advise Hana. (8 marks)', 8, 'Equitable lease and the register', 2, [
      { t: 'A lease over 7 years needs a deed and registration (s 53(1) CLPA; s 87 LTA); no legal lease here.', m: 2, k: ['§53|§87|deed|regist'] },
      { t: 'Walsh v Lonsdale: a specifically enforceable written agreement gives an equitable lease (s 6(d) writing; possession and rent).', m: 2, k: ['walsh|lonsdale|equitable lease'] },
      { t: 'Dev registered as a purchaser: indefeasible (s 46(1)); knowledge is not fraud (s 47(2)); the 9-year lease is not an overriding short lease; no caveat was lodged.', m: 3, k: ['§46|§47|indefeasib', 'caveat|7 years|overriding'] },
      { t: 'Hana likely loses against Dev; damages against Ms Goh; a Loke Yew-type promise never meant to be kept would be fraud.', m: 1, k: ['damages|goh|loke yew'] }
    ], '**Issue.** Does Hana hold a lease that binds Dev?\n\n**Law.** A lease over 7 years must be by deed and registered (**s 53(1) CLPA**; **s 87 LTA**). A signed agreement for a lease is treated in equity as a lease if specific performance is available (**Walsh v Lonsdale**). On registered land a registered purchaser takes free of unregistered interests unless protected (**s 46(1)**; **s 47(2)**; caveat under **s 115**). Only a lease of 7 years or less is an overriding interest.\n\n**Application.** Nine years is outside the short-lease exception; with no deed or registration Hana has no legal lease. Under Walsh v Lonsdale she holds an equitable lease: the agreement is in signed writing and she occupied and paid rent. But an equitable lease needs a caveat. Dev registered for value, and knowledge of Hana\'s occupation is not fraud. Unless Dev promised to honour the lease never meaning to (**Loke Yew**), his title is indefeasible.\n\n**Conclusion.** Hana likely loses against Dev and should claim damages from Ms Goh. Lodge a caveat whenever a lease over 7 years is agreed.') });

  drill({ id: 'q4', title: 'Building height and the shared road', src: 'Q&A Bank, Q4', chs: [3], marks: 8, parties: ['Ms Yap', 'Eve'],
    facts: 'Lim sold the front part of his land to Dev. In the sale, Dev promised "for himself and his successors" (i) not to build above two storeys and (ii) to pay half the cost of repairing the shared private road. The covenants are noted on the Certificate of Title. Dev sold to Eve, who built four storeys and refused to pay for the road. Lim\'s remaining land has since been sold to Ms Yap.',
    parts: one('Who can sue Eve, and for what? (8 marks)', 8, 'Benefit and burden of covenants', 3, [
      { t: 'Benefit: Ms Yap owns the retained land; covenants touch and concern it; benefit passes (Swift; annexation).', m: 2, k: ['benefit', 'swift|touch and concern|annex'] },
      { t: '(i) Height: negative; notice via the CT; Tulk v Moxhay: injunction (even an order to remove the extra storeys).', m: 3, k: ['tulk|moxhay', 'negative|restrictive', 'injunction'] },
      { t: '(ii) Road payment: positive; does not run (Austerberry; Rhone); Halsall v Brizell if Eve uses the road; or sue Dev (indemnity chain).', m: 3, k: ['austerberry|rhone|positive', 'halsall|brizell|dev|indemnit'] }
    ], '**Issue.** Can Ms Yap enforce (i) and (ii) against Eve?\n\n**Law.** Benefit passes at law if the covenant touches and concerns the dominant land and the other Swift conditions are met, or in equity by annexation. The burden does not run at common law (**Austerberry**; **Rhone v Stephens**); in equity a negative burden runs to a successor with notice (**Tulk v Moxhay**). A positive burden cannot run, though **Halsall v Brizell** applies where the successor takes a linked benefit.\n\n**Application.** Ms Yap owns the retained land and the covenants touch and concern it, so she holds the benefit. (i) is negative, benefits her land and is on the CT, so Eve has notice: injunction, possibly an order to remove the excess storeys. (ii) requires money, so it is positive and does not bind Eve at law or in equity; if Eve uses the road and the payment is the price of that use, Halsall v Brizell applies. Ms Yap can also sue Dev, the original covenantor, who may claim from Eve under any indemnity covenant.\n\n**Conclusion.** Ms Yap succeeds on (i) by injunction; on (ii) she relies on Halsall v Brizell or sues Dev.') });

  drill({ id: 'q5', title: 'The car park and the bicycle store', src: 'Q&A Bank, Q5', chs: [4], marks: 6, parties: ['Unit A', 'Unit B'],
    facts: 'Unit A shares a driveway with Unit B. A\'s owner claims a right to park two cars on B\'s driveway all day, Monday to Friday, and to store bicycles in a corner shed on B\'s land. B\'s owner, who now needs the driveway for his own cars, challenges both rights.',
    parts: one('Do these rights amount to easements? (6 marks)', 6, 'Four tests and ouster', 4, [
      { t: 'Re Ellenborough Park four tests; tests 1–3 met (separate owners; benefits Unit A).', m: 2, k: ['ellenborough|four tests|dominant'] },
      { t: 'All-day weekday parking takes away B\'s use: ouster (Batchelor v Marlow); a narrower right might pass.', m: 2, k: ['batchelor|marlow|ouster'] },
      { t: 'Shed storage amounts to possession (Copeland v Greenhalf): not an easement, at most a revocable licence.', m: 2, k: ['copeland|greenhalf|storage', 'licence'] }
    ], '**Issue.** Do the parking and storage rights amount to easements?\n\n**Law.** **Re Ellenborough Park**: dominant and servient tenements; accommodation; different owners; capable of grant, which excludes rights amounting to exclusive possession or ouster (**Copeland v Greenhalf**; **Batchelor v Marlow**).\n\n**Application.** Tests 1–3 are met. Parking all day on weekdays takes away B\'s use of the driveway during working hours, which Batchelor v Marlow held too much; it fails test 4. A right to park one car in a set space for limited periods might succeed. Storing bicycles in a shed on B\'s land is like Copeland v Greenhalf: possession, not an easement; at most a licence.\n\n**Conclusion.** Neither right is an easement as claimed; any licence is revocable.') });

  drill({ id: 'q7', title: 'The bank sells to its own subsidiary', src: 'Q&A Bank, Q7', chs: [5], marks: 8, parties: ['Rina', 'Bank X'],
    facts: 'Rina defaulted on her $1m mortgage. After one month\'s notice, Bank X sold her home to its subsidiary company for $1.1m. A valuation obtained by Rina shows it was worth $1.4m. The bank did not advertise the sale.',
    parts: one('Advise Rina. (8 marks)', 8, 'Mortgagee\'s duty on sale', 5, [
      { t: 'Power of sale arisen (deed, money due, no exclusion) and exercisable (s 25 CLPA trigger).', m: 2, k: ['§25|power of sale', 'arisen|exercisable'] },
      { t: 'Duty: good faith and reasonable care to obtain the true market value (Cuckmere); no duty to wait (China & South Sea Bank).', m: 3, k: ['cuckmere|market value|best price', 'good faith'] },
      { t: 'Apply: sale to own subsidiary, no advertising, about 21% below value: breach; set aside (subsidiary not innocent) or damages for about $300,000; account of proceeds.', m: 3, k: ['subsidiar|advertis', 'set aside|damages|300'] }
    ], '**Issue.** Did Bank X breach its duties on the exercise of the power of sale?\n\n**Law.** The power of sale arises (mortgage by deed, money due, no exclusion) and becomes exercisable under **s 25 CLPA**. The mortgagee must act in good faith and take reasonable care to obtain the true market value (**Cuckmere Brick v Mutual Finance**); it need not wait for a better market (**China & South Sea Bank v Tan Soon Gin**); a sale to itself or an associate at an undervalue is suspect.\n\n**Application.** The power appears exercisable after default and notice [check arrears]. Selling to its own subsidiary raises a conflict; no advertising means no test of the market; $1.1m is about 21% below $1.4m. That points to a lack of reasonable care.\n\n**Conclusion.** Rina can seek to set the sale aside (the subsidiary is not an innocent buyer) or claim about $300,000, plus an account of the proceeds.') });

  drill({ id: 'q8', title: 'The moneylender and the hawker\'s shop', src: 'Q&A Bank, Q8', chs: [5], marks: 8, parties: ['the hawker'],
    facts: 'An elderly, illiterate hawker borrowed $50,000 from a lender on terms of a 3-year lock-in, 30% default interest a year (contract rate 8%), and a clause giving the lender an option to buy his shop for $200,000 if he defaults. The shop is worth $600,000.',
    parts: one('Advise the hawker. (8 marks)', 8, 'Clogs, penalty, unconscionability', 5, [
      { t: 'Borrower profile: elderly and illiterate, like the sisters in Hong Leong; BOM v BOK (infirmity exploited, burden shifts).', m: 2, k: ['hong leong|bom v bok|unconscionab', 'vulnerab|illiterate|elderly'] },
      { t: '30% against 8%: a penalty (Hong Leong); contract rate only.', m: 2, k: ['penalt'] },
      { t: 'Option to buy at $200,000: part of the mortgage, a void clog (Samuel v Jarrah Timber).', m: 2, k: ['samuel|jarrah|option', 'clog'] },
      { t: 'Three-year lock-in: not illusory, likely valid (Fairclough v Knightsbridge); redeem on principal, contract interest and costs.', m: 2, k: ['fairclough|knightsbridge|lock', 'redeem'] }
    ], '**Issue.** Are the lock-in, default interest and option enforceable?\n\n**Law.** Clogs on the equity of redemption are void (**Fairclough**). A lender cannot take an option to buy as part of the mortgage (**Samuel v Jarrah Timber**). A default rate out of all proportion to the greatest conceivable loss is a penalty (**Hong Leong Finance v Tan Gin Huay**). Unconscionability: infirmity, exploitation, then the lender must prove fairness (**BOM v BOK**).\n\n**Application.** The borrower is vulnerable, like the sisters in Hong Leong. 30% against 8% is a penalty. A right to buy a $600,000 shop for $200,000 on default is part of the mortgage and stops him recovering his property: void, and also unconscionable. Three years is not illusory, so the lock-in likely stands unless the early-repayment charge is disproportionate.\n\n**Conclusion.** The default interest and option are unenforceable; the lock-in probably stands; he redeems on principal, contract interest and costs.') });

  drill({ id: 'q9', title: 'Late rent and the secret sublet', src: 'Q&A Bank, Q9', chs: [6], marks: 8, parties: ['Joe', 'Mr Pan'],
    facts: 'Joe leased a flat from Mr Pan for 3 years, with a clause permitting re-entry for breach. Joe paid rent two months late. Mr Pan accepted the late rent a week after he discovered that Joe had sublet a room without consent, which the lease forbids. Mr Pan now serves notice to end the lease.',
    parts: one('Advise Joe and Mr Pan. (8 marks)', 8, 'Forfeiture and waiver', 6, [
      { t: 'Forfeiture needs a right to re-enter (express clause; s 93 LTA only for registered leases) and the right procedure.', m: 2, k: ['re-?entry|forfeit', '§93|express'] },
      { t: 'Rent: s 18A CLPA lets Joe pay arrears and costs and end the action.', m: 2, k: ['18a'] },
      { t: 'Sublet: Mr Pan accepted rent knowing of it: waiver (Expert Clothing [check]); a continuing breach may give a fresh right; s 18 notice for non-rent breaches.', m: 4, k: ['waiv', '§18|notice|continuing'] }
    ], '**Issue.** Can Mr Pan forfeit for the late rent or the unauthorised sublet?\n\n**Law.** Forfeiture needs (1) a right to forfeit and (2) the right procedure. A lease of 7 years or less is unregistered, so the right must be express (**s 93 LTA** applies to registered leases). Non-rent breaches: **s 18 CLPA** notice, and the tenant may seek relief. Rent: **s 18A** lets the tenant pay arrears and costs. Accepting rent with knowledge of a breach waives forfeiture for it (**Expert Clothing** [check]).\n\n**Application.** Mr Pan has an express right. On rent, Joe can pay the arrears and costs under s 18A. On the sublet, Mr Pan accepted rent a week after learning of it: waiver, though a continuing breach may give a fresh right. [check whether s 18 notice applies to a sublet breach on your slides.]\n\n**Conclusion.** Mr Pan is unlikely to succeed; Joe should pay the arrears at once.') });

  drill({ id: 'q10', title: 'The hoardings and the restaurant', src: 'Q&A Bank, Q10', chs: [6], marks: 8, parties: ['the restaurateur', 'the mall owner'],
    facts: 'A restaurateur leased a unit in a mall for 5 years. The lease says rent is payable "without set-off or deduction". The mall owner installed hoardings across the main entrance during a 6-month renovation. Customers fell by 50%. The restaurateur stopped paying rent and sued for derogation from grant. The landlord re-entered for non-payment.',
    parts: one('Advise the restaurateur. (8 marks)', 8, 'Quiet enjoyment, derogation and set-off', 6, [
      { t: 'Quiet enjoyment and non-derogation: substantial interference judged by what both sides contemplated; landlord does not underwrite profitability (OUE v Three Sixty; Cold Storage).', m: 3, k: ['quiet enjoyment|derogat', 'oue|three sixty|cold storage'] },
      { t: 'Hoardings across the entrance for 6 months: physical interference with access, closer to substantial interference than Cold Storage\'s paid parking: a damages claim.', m: 2, k: ['hoarding|access|damages'] },
      { t: 'No-set-off clause is effective (OUE): withholding rent was a breach; re-entry likely valid; relief under s 18A by paying arrears and costs.', m: 3, k: ['set-?off', '18a|re-?entry'] }
    ], '**Issue.** Did the landlord derogate from grant or breach quiet enjoyment, and could the tenant withhold rent?\n\n**Law.** Quiet enjoyment and non-derogation are implied; the test is substantial interference with ordinary enjoyment, and the landlord does not underwrite profitability (**OUE v Three Sixty**; **Cold Storage v MCST Chancery Court**). A no-set-off clause is effective (**OUE**).\n\n**Application.** Hoardings across the main entrance for six months physically interfere with access, closer to substantial interference than the paid parking in Cold Storage. The tenant has a real damages claim. But the lease barred set-off, so withholding rent was a breach and re-entry for non-payment is likely valid, as in OUE. The tenant should have paid and sued; it may still seek relief under s 18A by paying arrears and costs.\n\n**Conclusion.** Damages claim for the interference, but the lease is likely lost unless the tenant pays under s 18A.') });

  drill({ id: 'q11', title: 'Rooms in Su Ling\'s shared flat', src: 'Q&A Bank, Q11', chs: [6], marks: 6, parties: ['Tom', 'Su Ling'],
    facts: 'Owner Su Ling signed separate agreements with Tom, Uma and Vik on different dates for three bedrooms in her flat. Each is headed "licence". A clause says Su Ling may move any occupier to another room. She has never done so. She now gives Tom 7 days\' notice. Tom says he is a tenant.',
    parts: one('Advise Tom. (6 marks)', 6, 'Lease or licence', 6, [
      { t: 'Street v Mountford: exclusive possession for a term at a rent; label irrelevant.', m: 2, k: ['mountford', 'exclusive possession'] },
      { t: 'The moving clause is a sham (Antoniades v Villiers); separate agreements at different times: no joint tenancy (AG Securities), but Tom is tenant of his own room.', m: 3, k: ['sham|antoniades', 'ag securities|separate'] },
      { t: 'Term unclear, so a periodic tenancy: valid notice for one rental period [check].', m: 1, k: ['periodic'] }
    ], '**Issue.** Is Tom a tenant or a licensee?\n\n**Law.** **Street v Mountford**: exclusive possession for a term at a rent is a tenancy whatever the label. Clauses never intended to operate are shams (**Antoniades v Villiers**; **AG Securities v Vaughan**). Separate agreements for different rooms mean no joint tenancy.\n\n**Application.** Tom pays rent for his own bedroom and can exclude others. The moving clause has never been used: a sham. The label "licence" is not decisive. The term is unclear, so he holds a periodic tenancy, ended only by proper notice for a rental period [check].\n\n**Conclusion.** Tom is a tenant of his room; 7 days\' notice may be too short depending on the rental period.') });

  /* ---- Lots 7–10 ---- */
  drill({ id: 'q12', title: 'The declaration that was never registered', src: 'Q&A Bank, Q12', chs: [7], marks: 6, parties: ['Dan', 'Ben and Cai'],
    facts: 'Three siblings, Ann, Ben and Cai, own a shophouse as joint tenants. Ann signed a declaration of severance in the approved form and posted copies to Ben and Cai on Monday. She died on Wednesday before the declaration was registered. Her Will leaves "all my property" to her son, Dan.',
    parts: one('Who owns Ann\'s share? (6 marks)', 6, 'Statutory severance', 7, [
      { t: 'Survivorship; a Will cannot pass a joint share (Shafeeg).', m: 2, k: ['survivorship', 'will'] },
      { t: 'Three statutory steps; effect on registration (Chan Lung Kien, overruling Diaz v Diaz); registration missing.', m: 3, k: ['chan lung kien|diaz', 'regist'] },
      { t: 'No equitable severance (Williams v Hensman): Ben and Cai take the whole; Dan nothing.', m: 1, k: ['hensman|ben|cai|dan'] }
    ], '**Issue.** Was the joint tenancy severed before Ann died?\n\n**Law.** Survivorship means nothing passes by Will (**Shafeeg v Fatimah**). Statutory severance needs declaration, service and registration, taking effect on registration (**s 53(5), (6) LTA**; **Chan Lung Kien**, overruling **Diaz v Diaz**). Equity also severs by acting on one\'s share, agreement or course of dealing (**Williams v Hensman**). A Will does not sever.\n\n**Application.** Ann completed steps 1 and 2 only; without registration there is no statutory severance. A unilateral declaration is not an act on her share, and no agreement appears.\n\n**Conclusion.** Ben and Cai take the whole by survivorship; Dan receives nothing from the shophouse.') });

  drill({ id: 'q13', title: 'Mdm Wee, Joy and the flat', src: 'Q&A Bank, Q13', chs: [7], marks: 8, parties: ['Mdm Wee', 'Joy'],
    facts: 'Mdm Wee paid the full $900,000 price of a flat and had it registered in her daughter Joy\'s sole name. Mdm Wee and Joy later quarrelled. Mdm Wee says the flat is hers. Joy says it was a gift. No document exists.',
    parts: one('Advise Mdm Wee and Joy. (8 marks)', 8, 'Resulting trust and advancement', 7, [
      { t: 'Two-stage inquiry: actual intention first (Goh Swee Fang; Patricia Khoo: presumptions a last resort).', m: 2, k: ['intention', 'goh swee fang|patricia khoo|two-stage|last resort'] },
      { t: 'Evidence to look for: who paid tax, who lived there, who kept rent, messages.', m: 2, k: ['evidence|conduct|rent|tax'] },
      { t: 'Presumption of resulting trust (Dyer v Dyer; Lau Siew Kim: burden on the asserting party) met by presumption of advancement parent to child.', m: 3, k: ['resulting trust', 'advancement'] },
      { t: 'Relationship judged at the time of transfer; later quarrel carries little weight: Joy likely keeps the flat unless evidence shows Mdm Wee kept the benefit.', m: 1, k: ['time of (the )?transfer|quarrel|joy'] }
    ], '**Issue.** Who holds the beneficial interest?\n\n**Law.** First look for the transferor\'s actual intention (**Goh Swee Fang**); only if none is found apply the presumptions (**Patricia Khoo**). Paying for property in another\'s name raises a resulting trust (**Dyer v Dyer**; **Westdeutsche**); the asserting party bears the burden (**Lau Siew Kim**). Advancement applies parent to child, its strength depending on the relationship (**Lau Siew Kim**).\n\n**Application.** Joy says gift; Mdm Wee says hers; there is no document, so look at conduct: who paid property tax, who lived there or took the rent, any messages. If nothing emerges, the resulting trust presumption points to Mdm Wee but advancement from mother to daughter points to a gift, and on a close relationship advancement is likely to prevail. The later quarrel matters little: intention is judged at the transfer.\n\n**Conclusion.** Joy probably keeps the flat, unless Mdm Wee shows she meant to keep the benefit (Patricia Khoo scenario 2 or 3).') });

  drill({ id: 'q14', title: 'Ken, Lily and unequal contributions', src: 'Q&A Bank, Q14', chs: [7], marks: 8, parties: ['Lily', 'Ken\'s brother'],
    facts: 'Ken and Lily, an unmarried couple, bought a flat in joint names. Ken paid 90% of the price from his savings. Lily paid 10%. Ken says the flat is his except for Lily\'s 10%. Lily says they agreed to hold equally. Ken has since died intestate.',
    parts: one('Advise Lily and Ken\'s brother. (8 marks)', 8, 'Joint names and unequal contributions', 7, [
      { t: 'Joint tenants at law (s 53(1) LTA).', m: 1, k: ['§53|joint tenan'] },
      { t: 'Unequal contributions at acquisition: purchase-money resulting trust 90:10 (Lau Siew Kim; Chan Yuen Lan), making them tenants in common in equity and ending survivorship.', m: 3, k: ['resulting trust', '90|tenan(ts?|cy) in common|proportion'] },
      { t: 'Lily\'s route: proved common intention to share equally (CICT; DOP v DOO); no presumption of advancement for unmarried partners [check].', m: 3, k: ['common intention|cict|dop v doo', 'advancement|unmarried'] },
      { t: 'Outcomes: 90:10 means Ken\'s share passes on intestacy (brother); equal joint tenancy in equity means Lily takes all by survivorship.', m: 1, k: ['intestac|brother|survivorship'] }
    ], '**Issue.** How do Ken and Lily hold the flat at law and in equity?\n\n**Law.** Joint names without words of severance give a joint tenancy at law (**s 53(1) LTA**). Unequal contributions at acquisition give a resulting trust in proportion (**Lau Siew Kim**; **Su Emmanuel**), unless a common intention shows otherwise (**Chan Yuen Lan**; **DOP v DOO**). Advancement is not generally available between unmarried partners [check].\n\n**Application.** They are legal joint tenants. Ken paid 90%, so equity presumes a 90:10 resulting trust, turning them into tenants in common and ending survivorship. If Lily proves a common intention at acquisition to share equally, equal shares prevail, as in DOP v DOO.\n\n**Conclusion.** If 90:10, Ken\'s 90% passes on intestacy and his brother benefits; if a beneficial joint tenancy is proved, Lily takes everything by survivorship.') });

  drill({ id: 'q16', title: 'Exercise by email after the deadline', src: 'Q&A Bank, Q16', chs: [8], marks: 6, parties: ['the buyer', 'the seller'],
    facts: 'An OTP says it is exercisable by delivering written notice with a cheque for 1% to the seller\'s solicitors by 5 pm on Friday. The buyer emailed a scan of the notice at 6 pm on Friday and delivered the cheque on Monday. The seller refuses to proceed and has accepted a higher offer.',
    parts: one('Advise the buyer. (6 marks)', 6, 'Strict exercise of an OTP', 8, [
      { t: 'Option must be exercised in the stated mode and time (Spiro); compliance is strict (JT Chanrai).', m: 2, k: ['spiro|chanrai', 'strict|mode'] },
      { t: 'Apply: an hour late, by email rather than delivery, cheque on Monday: lapsed at 5 pm.', m: 3, k: ['late|lapse|5 ?pm|deadline'] },
      { t: 'Only argument: waiver by the seller (weak); no contract, so the seller may sell.', m: 1, k: ['waiv'] }
    ], '**Issue.** Was the option validly exercised?\n\n**Law.** The option must be exercised in the mode and time it requires (**Spiro v Glencrown**); compliance is strict (**JT Chanrai**). The contract arises on exercise; a missed deadline means the option lapses.\n\n**Application.** The notice was sent an hour late, by email rather than delivery, and the cheque came on Monday. Every step missed the OTP\'s terms. The buyer can argue waiver or that time was not of the essence, but options are strictly construed and nothing shows the seller waived.\n\n**Conclusion.** The option lapsed; no contract; the seller may sell to the higher bidder.') });

  drill({ id: 'q18', title: 'The oral deal and the renovation', src: 'Q&A Bank, Q18', chs: [8], marks: 8, parties: ['Sam', 'Tan'],
    facts: 'Tan orally agreed to sell his shophouse to Sam for $3m. Sam paid $300,000, took possession and spent $150,000 on renovations over four months. Tan then refused to proceed, saying nothing is in writing.',
    parts: one('Advise Sam. (8 marks)', 8, 'Writing and part performance', 8, [
      { t: 's 6(d) CLA: signed writing with the 3 Ps; check whether receipts or messages form a memorandum.', m: 2, k: ['6a?\\s*\\(d\\)|memorandum|signed writing'] },
      { t: 'Part performance: concluded oral contract plus acts unequivocally referable (Hu Lee Impex; Maddison v Alderson).', m: 3, k: ['part performance', 'hu lee|maddison|unequivocal'] },
      { t: 'Apply: payment, possession and major renovation point clearly to a contract for this shophouse.', m: 2, k: ['possession|renovat'] },
      { t: 'Specific performance likely (land unique; EC Investment); caveat justified.', m: 1, k: ['specific performance|caveat'] }
    ], '**Issue.** Can Sam enforce an oral contract for land?\n\n**Law.** A land contract is enforceable only with a signed memorandum (**s 6(d) CLA**), unless part performance applies: a concluded oral contract and acts by the claimant unequivocally referable to it (**Hu Lee Impex**; **Maddison v Alderson**). Specific performance needs clean hands and inadequate damages (**EC Investment**).\n\n**Application.** Receipts or messages for the $300,000 might form a memorandum if they carry the 3 Ps and Tan\'s signature. If not, part performance applies: payment, possession and $150,000 of renovation point to ownership of this shophouse; a stranger would not renovate it. Land is unique and Sam has changed his position.\n\n**Conclusion.** Sam can likely enforce by part performance and seek specific performance; he should caveat, as he holds an equitable interest.') });

  drill({ id: 'q21', title: 'Removing Daniel\'s caveat', src: 'Q&A Bank, Q21', chs: [9], marks: 8, parties: ['Farah', 'Daniel'],
    facts: 'Daniel says Farah orally agreed to sell him her shophouse and that he paid $20,000. He lodged a caveat. Farah says she never agreed, she is about to sell to another buyer who has paid a deposit, and Daniel\'s money was a loan.',
    parts: one('Advise Farah. (8 marks)', 8, 'Caveat removal', 9, [
      { t: 'Open with the route: s 127(1) (caveator must show cause) rather than s 127(2) (vexatious, frivolous, bad faith) because facts are disputed.', m: 3, k: ['§127', '127\\s*\\(1\\)|127\\s*\\(2\\)|vexatious'] },
      { t: 'American Cyanamid / Eng Mee Yong: serious question to be tried (oral deal, $20,000, possible part performance), then balance of convenience.', m: 3, k: ['cyanamid|eng mee yong', 'serious question|balance of convenience'] },
      { t: 's 124 undertaking or security if the caveat stays; s 128 compensation for a wrongful caveat.', m: 2, k: ['§124|§128|undertaking|compensat'] }
    ], '**Issue.** Which route applies to remove the caveat, and will it succeed?\n\n**Law.** **s 127(1)**: any reason; the caveator must show cause. **s 127(2)**: lodged vexatiously, frivolously or not in good faith. Where facts are disputed, apply **American Cyanamid**: a serious question to be tried (**Eng Mee Yong**), then the balance of convenience. **s 124** allows an undertaking or security; **s 128** gives compensation for a wrongful caveat.\n\n**Application.** Farah should use s 127(1): the claim is genuinely disputed, so s 127(2) is harder. Daniel\'s claim rests on an oral agreement and a payment that may be part performance; arguable only if he has documents. On balance of convenience Farah loses a sale and faces a claim by the buyer who paid a deposit, while Daniel can be compensated in money.\n\n**Conclusion.** Fair prospect of removal if Daniel\'s evidence is thin; otherwise ask for an undertaking and security under s 124.') });

  drill({ id: 'q23', title: 'Rita takes commission from both sides', src: 'Q&A Bank, Q23', chs: [10], marks: 6, parties: ['Mr Foo', 'Rita'],
    facts: 'Agent Rita acted for the seller Mr Foo and also for the buyer Ms Gan on the same condominium sale. Rita took a commission from both without telling either that she was acting for the other.',
    parts: one('Advise Mr Foo. (6 marks)', 6, 'Dual agency', 10, [
      { t: 'Fiduciary cannot act for both sides without full disclosure and informed consent; CEA rules bar double commission without consent.', m: 2, k: ['fiduciar|both (sides|parties)', 'consent|disclos|cea'] },
      { t: 'Commission from Ms Gan is a secret commission: account (Hippisley); dishonest agent forfeits commission (Andrews v Ramsay).', m: 3, k: ['secret', 'hippisley|andrews|forfeit|account'] },
      { t: 'If terms were affected, rescission or damages; CEA complaint.', m: 1, k: ['rescind|rescission|damages|complain'] }
    ], '**Issue.** Is Rita in breach, and what can Mr Foo recover?\n\n**Law.** An agent cannot act for both sides without full disclosure and informed consent; the CEA rules bar commission from both sides without consent. A secret profit must be accounted for (**Hippisley**); a dishonest agent forfeits commission (**Andrews v Ramsay**).\n\n**Application.** Rita had an undisclosed conflict and took a secret commission from Ms Gan. Mr Foo had no chance to consent.\n\n**Conclusion.** Mr Foo can make Rita account for Ms Gan\'s commission, refuse his own, report her to the CEA, and rescind or claim damages if the terms suffered.') });

  drill({ id: 'q24', title: 'Exclusive agency and the neighbour', src: 'Q&A Bank, Q24', chs: [10], marks: 6, parties: ['Mr Chen', 'Ali'],
    facts: 'Mr Chen gave Agent Ali an exclusive agency for 3 months at 1% commission under the CEA form. During the period Mr Chen sold to his neighbour, whom Ali never met. Mr Chen refuses to pay.',
    parts: one('Advise Mr Chen and Ali. (6 marks)', 6, 'Exclusive agency commission', 10, [
      { t: 'CEA exclusive form, Clause 6: commission due on any binding sale in the validity period, whether or not the agent introduced the buyer.', m: 3, k: ['clause 6|exclusive', 'validity|binding'] },
      { t: 'Effective cause (Grandhome) is for non-exclusive agency only.', m: 2, k: ['grandhome|effective cause'] },
      { t: 'If an OTP was used, the binding agreement arises on exercise (Spiro), which fixes whether it fell in the period.', m: 1, k: ['spiro|exercis'] }
    ], '**Issue.** Is commission payable although Ali did not introduce the buyer?\n\n**Law.** Under the CEA exclusive form, **Clause 6**, commission is payable if during the validity period the seller enters a binding agreement for sale, whether or not the agent introduced the buyer. Effective cause (**Grandhome**) applies only to non-exclusive agency.\n\n**Application.** The agency was exclusive and the sale was made within three months, so Ali\'s role is irrelevant. If an OTP was involved, the binding agreement arises on exercise (**Spiro**), which decides whether the sale fell inside the period.\n\n**Conclusion.** Mr Chen owes Ali 1% if the binding agreement arose within the validity period.') });
})(window.LL);
